-- Sinh tự động bởi scripts/content-to-sql.ts — đừng sửa tay.
begin;
on conflict (id) do update set kind=excluded.kind,title=excluded.title,authors=excluded.authors,journal=excluded.journal,publisher=excluded.publisher,year=excluded.year,doi=excluded.doi,url=excluded.url,license=excluded.license,cited_by=excluded.cited_by,note=excluded.note;
on conflict (id) do update set system=excluded.system,mesh_names=excluded.mesh_names,name_vi=excluded.name_vi,name_latin=excluded.name_latin,name_latin_ta2=excluded.name_latin_ta2,name_en=excluded.name_en,grp=excluded.grp,layer=excluded.layer,description=excluded.description,"function"=excluded."function",clinical=excluded.clinical,mnemonic=excluded.mnemonic,source=excluded.source,reviewed_by=excluded.reviewed_by,reviewed_at=excluded.reviewed_at,updated_at=now();
delete from public.structure_sources where structure_id in (select id from public.structures where system='cardiovascular');
delete from public.questions where system='cardiovascular';
commit;
