insert into public.structures (id,system,mesh_names,name_vi,name_latin,name_latin_ta2,name_en,grp,layer,description,"function",clinical,mnemonic,source,reviewed_by,reviewed_at,updated_at) values
('right_atrium','cardiovascular',array['Right atrium']::text[],'Tâm nhĩ phải','Atrium dextrum',null,'Right atrium','chambers',1,'Buồng tim ở phía trên bên phải, nhận máu từ tĩnh mạch chủ trên, tĩnh mạch chủ dưới và xoang vành. Mặt trong có phần thành nhẵn và phần có cơ lược.','Thu nhận máu nghèo oxy từ toàn cơ thể và đẩy xuống tâm thất phải qua van ba lá.','Nút xoang nhĩ (nút tạo nhịp tự nhiên) nằm ở thành tâm nhĩ phải, gần lỗ tĩnh mạch chủ trên.',null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('right_ventricle','cardiovascular',array['Right ventricle']::text[],'Tâm thất phải','Ventriculus dexter',null,'Right ventricle','chambers',1,'Buồng tim ở phía trước, tạo nên phần lớn mặt ức sườn của tim. Thành mỏng hơn tâm thất trái, mặt trong có nhiều bè cơ.','Bơm máu nghèo oxy lên phổi qua van động mạch phổi và thân động mạch phổi.','Phì đại thất phải gặp trong tăng áp động mạch phổi kéo dài.',null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('left_atrium','cardiovascular',array['Left atrium']::text[],'Tâm nhĩ trái','Atrium sinistrum',null,'Left atrium','chambers',1,'Buồng tim ở phía sau, nhận máu từ bốn tĩnh mạch phổi. Tạo nên phần lớn nền tim.','Thu nhận máu giàu oxy từ phổi và đẩy xuống tâm thất trái qua van hai lá.','Giãn nhĩ trái thường gặp trong hẹp van hai lá và là yếu tố nguy cơ của rung nhĩ.',null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('left_ventricle','cardiovascular',array['Left ventricle']::text[],'Tâm thất trái','Ventriculus sinister',null,'Left ventricle','chambers',1,'Buồng tim có thành dày nhất, tạo nên mỏm tim và phần lớn mặt hoành của tim.','Bơm máu giàu oxy vào động mạch chủ để đi nuôi toàn cơ thể.','Phì đại thất trái là hậu quả thường gặp của tăng huyết áp kéo dài.',null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('papillary_muscles_rv','cardiovascular',array['Anterior papillary muscle of right ventricle','Inferior papillary muscle of right ventricle','Septal papillary muscle of right ventricle']::text[],'Cơ nhú tâm thất phải','Musculi papillares ventriculi dextri',null,'Papillary muscles of right ventricle','chambers',2,'Ba cơ nhú (trước, dưới và vách) nằm trong tâm thất phải, nối với các lá van ba lá bằng thừng gân.','Co cùng tâm thất để giữ các lá van ba lá không lật ngược lên tâm nhĩ trong thì tâm thu.',null,null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('papillary_muscle_lv','cardiovascular',array['Inferior papillary muscle of left ventricle']::text[],'Cơ nhú tâm thất trái','Musculi papillares ventriculi sinistri',null,'Papillary muscles of left ventricle','chambers',2,'Hai cơ nhú (trước và sau) nằm trong tâm thất trái, nối với hai lá van hai lá bằng thừng gân. Mô hình chỉ có cơ nhú sau; cơ nhú trước không có trong dữ liệu nguồn.','Giữ các lá van hai lá đóng kín trong thì tâm thu.','Đứt cơ nhú sau nhồi máu cơ tim gây hở van hai lá cấp.',null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('tricuspid_valve','cardiovascular',array['Inferior leaflet of right atrioventricular valve','Septal leaflet of right atrioventricular valve']::text[],'Van ba lá','Valva tricuspidalis (valva atrioventricularis dextra)','Valva atrioventricularis dextra','Tricuspid valve','valves',2,'Van nhĩ thất phải, có ba lá van (trước, sau và vách), nằm giữa tâm nhĩ phải và tâm thất phải. Mô hình có lá sau và lá vách; lá trước không có trong dữ liệu nguồn.','Ngăn máu trào ngược từ tâm thất phải lên tâm nhĩ phải trong thì tâm thu.','Nghe rõ nhất ở bờ trái xương ức, khoang liên sườn 4–5.',null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('mitral_valve','cardiovascular',array['Posterior leaflet of left atrioventricular valve']::text[],'Van hai lá','Valva mitralis (valva atrioventricularis sinistra)','Valva atrioventricularis sinistra','Mitral valve','valves',2,'Van nhĩ thất trái, có hai lá van (lá trước và lá sau), nằm giữa tâm nhĩ trái và tâm thất trái. Mô hình hiển thị van như một khối, không tách riêng hai lá.','Ngăn máu trào ngược từ tâm thất trái lên tâm nhĩ trái trong thì tâm thu.','Hẹp van hai lá thường do thấp tim; nghe rõ nhất ở mỏm tim.',null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('aortic_valve','cardiovascular',array['Left coronary leaflet','Right coronary leaflet','Non-coronary leaflet']::text[],'Van động mạch chủ','Valva aortae',null,'Aortic valve','valves',2,'Van bán nguyệt có ba lá: lá vành trái, lá vành phải và lá không vành. Phía trên các lá van là các xoang động mạch chủ.','Ngăn máu từ động mạch chủ chảy ngược về tâm thất trái trong thì tâm trương.','Động mạch vành trái và phải xuất phát từ xoang vành trái và phải ngay trên van.',null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('pulmonary_valve','cardiovascular',array['Anterior semilunar leaflet of pulmonary valve','Left semilunar leaflet of pulmonary valve','Right semilunar leaflet of pulmonary valve']::text[],'Van động mạch phổi','Valva trunci pulmonalis',null,'Pulmonary valve','valves',2,'Van bán nguyệt có ba lá (trước, trái, phải), nằm ở lỗ thân động mạch phổi.','Ngăn máu từ thân động mạch phổi chảy ngược về tâm thất phải trong thì tâm trương.',null,null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('ascending_aorta','cardiovascular',array['Ascending aorta']::text[],'Động mạch chủ lên','Pars ascendens aortae','Aorta ascendens','Ascending aorta','great_arteries',0,'Đoạn đầu của động mạch chủ, dài khoảng 5 cm, đi từ tâm thất trái lên đến chỗ bắt đầu cung động mạch chủ.','Dẫn máu từ tâm thất trái; cho hai nhánh đầu tiên là động mạch vành trái và phải.',null,null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('aortic_arch','cardiovascular',array['Aortic arch']::text[],'Cung động mạch chủ','Arcus aortae',null,'Aortic arch','great_arteries',0,'Đoạn cong của động mạch chủ, uốn từ trước ra sau và sang trái, phía trên chỗ chia đôi của thân động mạch phổi.','Cho ba nhánh lớn cấp máu cho đầu, cổ và chi trên: thân cánh tay đầu, động mạch cảnh chung trái, động mạch dưới đòn trái.','Dây chằng động mạch (di tích ống động mạch) nối cung động mạch chủ với động mạch phổi trái.',null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('thoracic_aorta','cardiovascular',array['Thoracic aorta']::text[],'Động mạch chủ ngực','Pars thoracica aortae','Aorta thoracica','Thoracic (descending) aorta','great_arteries',0,'Đoạn động mạch chủ xuống nằm trong trung thất sau, từ bờ dưới đốt sống ngực IV đến lỗ động mạch chủ của cơ hoành.','Cấp máu cho thành ngực và các tạng trong ngực qua các động mạch gian sườn sau, phế quản, thực quản.',null,null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('brachiocephalic_trunk','cardiovascular',array['Brachiocephalic trunk']::text[],'Thân cánh tay đầu','Truncus brachiocephalicus',null,'Brachiocephalic trunk','great_arteries',0,'Nhánh đầu tiên và lớn nhất của cung động mạch chủ, chia thành động mạch cảnh chung phải và động mạch dưới đòn phải.','Cấp máu cho nửa phải của đầu, cổ và chi trên phải.',null,null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('right_common_carotid','cardiovascular',array['Right common carotid artery']::text[],'Động mạch cảnh chung phải','Arteria carotis communis dextra','Carotis communis dextra','Right common carotid artery','great_arteries',0,'Xuất phát từ thân cánh tay đầu, đi lên cổ trong bao cảnh và chia thành động mạch cảnh trong và cảnh ngoài.','Cấp máu cho đầu và cổ bên phải.',null,null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('left_common_carotid','cardiovascular',array['Left common carotid artery']::text[],'Động mạch cảnh chung trái','Arteria carotis communis sinistra','Carotis communis sinistra','Left common carotid artery','great_arteries',0,'Xuất phát trực tiếp từ cung động mạch chủ, dài hơn bên phải vì có thêm đoạn trong ngực.','Cấp máu cho đầu và cổ bên trái.',null,null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('right_subclavian','cardiovascular',array['Right subclavian artery']::text[],'Động mạch dưới đòn phải','Arteria subclavia dextra',null,'Right subclavian artery','great_arteries',0,'Xuất phát từ thân cánh tay đầu, uốn cong qua đỉnh phổi và đi ra ngoài phía sau xương đòn.','Cấp máu cho chi trên phải, một phần cổ và não (qua động mạch đốt sống).',null,null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('left_subclavian','cardiovascular',array['Left subclavian artery']::text[],'Động mạch dưới đòn trái','Arteria subclavia sinistra',null,'Left subclavian artery','great_arteries',0,'Nhánh thứ ba của cung động mạch chủ, đi lên rồi ra ngoài qua đỉnh phổi trái.','Cấp máu cho chi trên trái, một phần cổ và não.',null,null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('pulmonary_trunk','cardiovascular',array['Pulmonary trunk','Bifurcation of pulmonary trunk']::text[],'Thân động mạch phổi','Truncus pulmonalis',null,'Pulmonary trunk','great_arteries',0,'Xuất phát từ tâm thất phải, dài khoảng 5 cm, đi lên và ra sau rồi chia thành động mạch phổi phải và trái dưới cung động mạch chủ.','Dẫn máu nghèo oxy từ tâm thất phải lên phổi.',null,null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('right_pulmonary_artery','cardiovascular',array['Right pulmonary artery']::text[],'Động mạch phổi phải','Arteria pulmonalis dextra',null,'Right pulmonary artery','great_arteries',0,'Nhánh dài hơn của thân động mạch phổi, đi ngang sang phải phía sau động mạch chủ lên và tĩnh mạch chủ trên để vào rốn phổi phải.','Dẫn máu nghèo oxy đến phổi phải.',null,null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('left_pulmonary_artery','cardiovascular',array['Left pulmonary artery']::text[],'Động mạch phổi trái','Arteria pulmonalis sinistra',null,'Left pulmonary artery','great_arteries',0,'Nhánh ngắn hơn, đi sang trái phía trước động mạch chủ xuống để vào rốn phổi trái.','Dẫn máu nghèo oxy đến phổi trái.',null,null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('superior_vena_cava','cardiovascular',array['Superior vena cava']::text[],'Tĩnh mạch chủ trên','Vena cava superior',null,'Superior vena cava','great_veins',0,'Được tạo bởi hai tĩnh mạch cánh tay đầu hợp lại, đi xuống bên phải động mạch chủ lên và đổ vào phần trên tâm nhĩ phải.','Dẫn máu nghèo oxy từ đầu, cổ, chi trên và thành ngực về tim.','Hội chứng tĩnh mạch chủ trên: phù mặt, cổ và chi trên do khối u trung thất chèn ép.',null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('inferior_vena_cava','cardiovascular',array['Inferior vena cava (thoracic part)']::text[],'Tĩnh mạch chủ dưới','Vena cava inferior',null,'Inferior vena cava','great_veins',0,'Tĩnh mạch lớn nhất cơ thể, đi qua lỗ tĩnh mạch chủ của cơ hoành ở mức đốt sống ngực VIII và đổ vào phần dưới tâm nhĩ phải. Mô hình chỉ có đoạn ngực.','Dẫn máu nghèo oxy từ phần cơ thể dưới cơ hoành về tim.',null,null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('right_brachiocephalic_vein','cardiovascular',array['Right brachiocephalic vein']::text[],'Tĩnh mạch cánh tay đầu phải','Vena brachiocephalica dextra',null,'Right brachiocephalic vein','great_veins',0,'Do tĩnh mạch cảnh trong phải và tĩnh mạch dưới đòn phải hợp thành sau khớp ức đòn phải, ngắn và đi gần thẳng đứng.','Cùng tĩnh mạch cánh tay đầu trái tạo nên tĩnh mạch chủ trên.',null,null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('left_brachiocephalic_vein','cardiovascular',array['Left brachiocephalic vein']::text[],'Tĩnh mạch cánh tay đầu trái','Vena brachiocephalica sinistra',null,'Left brachiocephalic vein','great_veins',0,'Dài hơn bên phải, đi chếch sang phải phía sau cán ức, bắt chéo trước các nhánh của cung động mạch chủ.','Cùng tĩnh mạch cánh tay đầu phải tạo nên tĩnh mạch chủ trên.',null,null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('right_pulmonary_veins','cardiovascular',array['Right superior pulmonary vein','Right inferior pulmonary vein']::text[],'Các tĩnh mạch phổi phải','Venae pulmonales dextrae','Vena pulmonalis dextra superior; Vena pulmonalis dextra inferior','Right pulmonary veins','great_veins',0,'Hai tĩnh mạch (trên và dưới) đi từ rốn phổi phải, phía sau tĩnh mạch chủ trên và tâm nhĩ phải, đổ vào tâm nhĩ trái.','Dẫn máu giàu oxy từ phổi phải về tâm nhĩ trái.',null,null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('left_pulmonary_veins','cardiovascular',array['Left superior pulmonary vein','Left inferior pulmonary vein']::text[],'Các tĩnh mạch phổi trái','Venae pulmonales sinistrae','Vena pulmonalis sinistra superior; Vena pulmonalis sinistra inferior','Left pulmonary veins','great_veins',0,'Hai tĩnh mạch (trên và dưới) đi từ rốn phổi trái, phía trước động mạch chủ xuống, đổ vào tâm nhĩ trái.','Dẫn máu giàu oxy từ phổi trái về tâm nhĩ trái.','Tĩnh mạch phổi là nguồn phát sinh thường gặp của rung nhĩ; là đích của thủ thuật cô lập tĩnh mạch phổi.',null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('left_coronary_artery','cardiovascular',array['Left coronary artery']::text[],'Động mạch vành trái','Arteria coronaria sinistra',null,'Left coronary artery','coronary',0,'Xuất phát từ xoang động mạch chủ trái, thân chung ngắn (khoảng 1–2 cm) rồi chia thành nhánh gian thất trước và nhánh mũ.','Cấp máu cho phần lớn tâm thất trái, tâm nhĩ trái và vách gian thất.','Hẹp thân chung động mạch vành trái là tổn thương nguy hiểm, thường chỉ định phẫu thuật bắc cầu.',null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('anterior_interventricular_artery','cardiovascular',array['Anterior interventricular artery','Septal branches of anterior interventricular artery']::text[],'Nhánh gian thất trước','Ramus interventricularis anterior','Arteria interventricularis anterior','Anterior interventricular (LAD) artery','coronary',0,'Nhánh của động mạch vành trái, chạy trong rãnh gian thất trước xuống mỏm tim, cho các nhánh vách và nhánh chéo.','Cấp máu cho thành trước hai tâm thất và hai phần ba trước của vách gian thất.','Tắc nhánh gian thất trước là nguyên nhân thường gặp nhất của nhồi máu cơ tim thành trước.',null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('circumflex_artery','cardiovascular',array['Circumflex artery of heart']::text[],'Nhánh mũ','Ramus circumflexus','Arteria circumflexa cordis','Circumflex artery','coronary',0,'Nhánh của động mạch vành trái, chạy trong rãnh vành vòng ra sau bên trái tim.','Cấp máu cho tâm nhĩ trái và thành bên, thành sau tâm thất trái.',null,null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('right_coronary_artery','cardiovascular',array['Right coronary artery','Right inferolateral branch of right coronary artery']::text[],'Động mạch vành phải','Arteria coronaria dextra',null,'Right coronary artery','coronary',0,'Xuất phát từ xoang động mạch chủ phải, chạy trong rãnh vành phải ra sau, thường tận cùng bằng nhánh gian thất sau.','Cấp máu cho tâm nhĩ phải, tâm thất phải, thường cả nút xoang nhĩ, nút nhĩ thất và phần sau vách gian thất.','Nhồi máu do tắc động mạch vành phải thường kèm rối loạn nhịp chậm do thiếu máu nút nhĩ thất.',null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('coronary_sinus','cardiovascular',array['Coronary sinus']::text[],'Xoang vành','Sinus coronarius',null,'Coronary sinus','coronary',0,'Tĩnh mạch lớn nằm trong rãnh vành ở mặt sau tim, dài khoảng 2–3 cm, đổ vào tâm nhĩ phải giữa lỗ tĩnh mạch chủ dưới và van ba lá.','Thu nhận phần lớn máu tĩnh mạch của tim (tĩnh mạch tim lớn, giữa, nhỏ) đưa về tâm nhĩ phải.',null,null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('great_cardiac_vein','cardiovascular',array['Great cardiac vein']::text[],'Tĩnh mạch tim lớn','Vena cordis magna','Vena magna cordis','Great cardiac vein','coronary',0,'Bắt đầu ở mỏm tim, đi lên trong rãnh gian thất trước cùng nhánh gian thất trước, vòng sang trái trong rãnh vành rồi đổ vào xoang vành.','Dẫn máu tĩnh mạch từ thành trước tim về xoang vành.',null,null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('middle_cardiac_vein','cardiovascular',array['Middle cardiac vein']::text[],'Tĩnh mạch tim giữa','Vena cordis media','Vena media cordis','Middle cardiac vein','coronary',0,'Đi trong rãnh gian thất sau cùng nhánh gian thất sau, đổ vào xoang vành.','Dẫn máu tĩnh mạch từ mặt hoành của tim về xoang vành.',null,null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now()),
('inferior_vein_lv','cardiovascular',array['Inferior vein of left ventricle','Inferior vein of left ventricle (//Posterior '''')']::text[],'Tĩnh mạch sau tâm thất trái','Vena ventriculi sinistri posterior','Vena inferior ventriculi sinistri','Posterior (inferior) vein of left ventricle','coronary',0,'Đi trên mặt hoành của tâm thất trái, đổ vào xoang vành hoặc tĩnh mạch tim lớn.','Dẫn máu tĩnh mạch từ mặt dưới tâm thất trái.',null,null,'BẢN NHÁP – chưa có cố vấn duyệt',null,null,now())
